<template x-if="config.module === 'dashboard'">
    <div class="backend-dashboard">
        <section class="welcome"><div><p class="eyebrow">UNE NOUVELLE JOURNÉE À L’ÉCOLE</p><h2>Chaque élève compte.</h2><p>Les repères essentiels pour accompagner votre école au quotidien.</p><div class="welcome-actions"><a x-show="permitted('enrollments.read')" href="/admin/enrollments" class="button white">Gérer les inscriptions <span>↗</span></a><a x-show="permitted('pedagogy.read')" href="/admin/schedule" class="welcome-link">Voir le planning →</a></div></div><div class="welcome-cycle"><x-filament::icon icon="heroicon-o-academic-cap"/><p x-text="school?.name"></p><small>Un espace commun pour faire grandir l’école.</small></div></section>
        <div class="stat-grid">
            <a href="/admin/students" class="stat" x-show="permitted('students.read')"><div class="stat-top">Dossiers élèves<x-filament::icon icon="heroicon-o-academic-cap"/></div><strong x-text="metric('students')"></strong><small>Tous les élèves de l’établissement</small></a>
            <a href="/admin/groups" class="stat" x-show="permitted('catalog.read')"><div class="stat-top">Classes et groupes<x-filament::icon icon="heroicon-o-user-group"/></div><strong x-text="metric('cohorts')"></strong><small>Vos groupes d’apprentissage</small></a>
            <a href="/admin/teachers" class="stat" x-show="permitted('hr.read')"><div class="stat-top">Enseignants actifs<x-filament::icon icon="heroicon-o-users"/></div><strong x-text="metric('teachers')"></strong><small>L’équipe pédagogique</small></a>
            <a href="/admin/finance" class="stat" x-show="permitted('finance.read')"><div class="stat-top">Solde à encaisser<x-filament::icon icon="heroicon-o-banknotes"/></div><strong class="currency" x-text="metric('balance_minor')"></strong><small>Solde des factures de l’école</small></a>
            <a href="/admin/enrollments" class="stat" x-show="!permitted('finance.read') && permitted('enrollments.read')"><div class="stat-top">Inscriptions<x-filament::icon icon="heroicon-o-clipboard-document-check"/></div><strong x-text="metric('enrollments')"></strong><small>Suivi des dossiers d’inscription</small></a>
        </div>
        <div class="dashboard-grid">
            <section class="surface" x-show="permitted('catalog.read') && permitted('enrollments.read')"><div class="section-top"><div><p class="eyebrow">SCOLARITÉ</p><h3>Vos cycles d’enseignement</h3></div><a href="/admin/groups">Les classes →</a></div>
                <template x-for="(cycle,index) in overview?.cycles || []" :key="cycle.name"><div class="cycle-row"><span class="cycle-icon" :class="'c'+index%3"><x-filament::icon icon="heroicon-o-academic-cap"/></span><div class="cycle-name"><strong x-text="cycle.name"></strong><small x-text="cycle.classes+' classe(s)'"></small></div><div class="cycle-bar"><span :style="{width:cycleWidth(cycle)}"></span></div><strong x-text="cycle.students"></strong><small>élèves</small></div></template>
                <p class="muted" x-show="!busy && !overview?.cycles?.length">Les programmes apparaîtront ici après leur création.</p><div class="soft-note">Les effectifs correspondent aux élèves ayant une inscription non annulée.</div>
            </section>
            <section class="surface"><div class="section-top"><div><p class="eyebrow">AU QUOTIDIEN</p><h3>Vos accès rapides</h3></div></div>
                <a x-show="permitted('enrollments.read')" class="priority" href="/admin/enrollments"><span class="priority-icon amber"><x-filament::icon icon="heroicon-o-clipboard-document-check"/></span><span><strong>Inscriptions en attente</strong><small>Examiner les dossiers et affecter les élèves</small></span><span class="badge amber" x-text="metric('pending')"></span></a>
                <a x-show="permitted('pedagogy.read')" class="priority" href="/admin/assessments"><span class="priority-icon blue"><x-filament::icon icon="heroicon-o-pencil-square"/></span><span><strong>Devoirs et examens</strong><small>Suivre les évaluations et les notes</small></span><span>→</span></a>
                <a x-show="permitted('hr.read')" class="priority" href="/admin/teachers"><span class="priority-icon primary"><x-filament::icon icon="heroicon-o-users"/></span><span><strong>L’équipe de l’école</strong><small>Enseignants, fonctions et affectations</small></span><span>→</span></a>
            </section>
        </div>
        <section class="surface" x-show="permitted('pedagogy.read') && permitted('catalog.read')"><div class="section-top"><div><p class="eyebrow">ORGANISATION</p><h3>Prochaines séances</h3></div><a href="/admin/schedule">Ouvrir le planning →</a></div><template x-for="session in overview?.upcoming || []" :key="session.id"><div class="agenda-row"><span class="agenda-time" x-text="display(session.starts_at,'starts_at')"></span><span class="agenda-line"></span><div><strong x-text="session.subject"></strong><small x-text="session.classroom+' · '+session.room"></small></div></div></template><div class="backend-empty" x-show="!busy && !overview?.upcoming?.length"><x-filament::icon icon="heroicon-o-calendar-days"/><h3>Votre planning est prêt à être rempli</h3><p>Les prochaines séances programmées apparaîtront ici.</p></div></section>
        <button class="backend-link" @click="loadOverview()" :disabled="busy">Actualiser le tableau de bord</button>
    </div>
</template>
